/* Monthly PO template picker. Templates are copied into the existing editable PO form. */
window.createMonthlyPO=({S,client,C,M,esc,heading,button,toast,internal,startDraft,download})=>{
 let headers=[],rows=[],review=[],period=M.today().slice(0,7),supplierId='',readEpoch=0,uploadEpoch=0,ready=false;
 const active=()=>S.page==='monthly'&&internal()&&document.querySelector('#monthly-root');
 const showError=e=>toast(e?.code==='40001'?'Master berubah. Tekan Muat ulang forecast, lalu unggah dan tinjau file kembali.':e?.code==='PGRST202'?'Master bulanan belum diaktifkan pada server.':e?.message||'Master belum dapat dimuat. Periksa koneksi.');
 const rpc=async(name,args)=>{const r=await client.rpc(name,{w:C.workspaceId,...args});if(r.error)throw r.error;return r.data};
 function page(){
  if(!internal())return;if(document.querySelector('#monthly-root'))return;
  document.querySelector('#main').innerHTML=heading('Forecast Bulan Ini','Impor template bulanan, pilih barang, lalu edit sebelum menyimpan PO.',button('PO Manual',"PO.go('create')"))+'<div id="monthly-root"><section class="panel import-box"><h2>Impor forecast</h2><p class="sub">Kolom: periode, kode supplier, kode barang, nama barang, satuan, qty awal.<br>Contoh periode: 2026-10. Format periode dan kode sebagai Teks di Excel. Supplier dan produk harus sudah terdaftar. Maksimal 5 MB / 10.000 baris.<br>Impor ulang memperbarui baris dengan periode, supplier, kode barang dan satuan yang sama; baris lain tetap tersimpan.</p><div class="buttons">'+button('Unduh Template CSV','PO.monthly.template()')+button('Muat ulang forecast','PO.monthly.reload()')+'</div><input type="file" aria-label="File forecast bulan ini" accept=".csv,.xlsx,.xls" onchange="PO.monthly.readFile(this.files[0])"><div id="monthly-review"></div></section><section class="panel monthly-picker"><h2>Buat PO dari forecast</h2><div class="draft-header"><div class="form-group"><label for="monthly-period">Periode</label><select id="monthly-period" onchange="PO.monthly.choosePeriod(this.value)"></select></div><div class="form-group"><label for="monthly-supplier">Supplier</label><select id="monthly-supplier" onchange="PO.monthly.chooseSupplier(this.value)"></select></div></div><div id="monthly-lines" aria-live="polite"></div></section></div>';
  ready=false;loadHeaders();
 }
 function selectors(){
  const periods=[...new Set([period,...headers.map(h=>h.period)])].sort().reverse();document.querySelector('#monthly-period').innerHTML=periods.map(p=>'<option '+(p===period?'selected':'')+' value="'+esc(p)+'">'+esc(new Date(p+'-01T00:00:00').toLocaleDateString('id-ID',{month:'long',year:'numeric'}))+'</option>').join('');
  const suppliers=S.data.suppliers.filter(s=>s.active);if(!suppliers.some(s=>s.id===supplierId))supplierId=suppliers[0]?.id||'';
  document.querySelector('#monthly-supplier').innerHTML=suppliers.map(s=>'<option '+(s.id===supplierId?'selected':'')+' value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join('');
 }
 async function loadHeaders(){const epoch=S.epoch;try{const data=await rpc('po_monthly_list',{});if(epoch!==S.epoch||!active())return;headers=data||[];ready=true;selectors();await loadRows()}catch(e){if(epoch===S.epoch&&active()){document.querySelector('#monthly-lines').textContent='Master belum dapat dimuat. Tekan Muat ulang forecast untuk mencoba lagi.';showError(e)}}}
 async function loadRows(){
  rows=[];const run=++readEpoch,epoch=S.epoch;if(!active())return;document.querySelector('#monthly-lines').innerHTML='<div class="monthly-loading" role="status"><span class="startup-ring" aria-hidden="true"></span> Memuat barang...</div>';
  try{const data=supplierId?await rpc('po_monthly_rows',{p:period,s:supplierId}):[];if(run!==readEpoch||epoch!==S.epoch||!active())return;rows=data||[];renderRows()}catch(e){if(run===readEpoch&&epoch===S.epoch&&active()){document.querySelector('#monthly-lines').textContent='Barang belum dapat dimuat.';showError(e)}}
 }
 function conversions(r,qty){const p=S.data.products.find(p=>p.id===r.product_code&&p.supplier_id===(r.supplier_id||supplierId));if(!p||!Number.isFinite(qty)||qty<0)return {crt:'\u2014',pcs:'\u2014'};const pack=M.productPack(p),source=pack.units.indexOf(r.unit);if(source<0)return {crt:'\u2014',pcs:'\u2014'};const base=qty*pack.factors[source],value=(unit,digits)=>{const i=pack.units.indexOf(unit);return i<0?'\u2014':(base/pack.factors[i]).toLocaleString('id-ID',{maximumFractionDigits:digits})};return {crt:value('CRT',1),pcs:value('PCS',10)}}
 function updateQty(index){const input=document.querySelector('.monthly-qty[data-index="'+index+'"]');if(!input)return;const result=conversions(rows[index],input.value===''?NaN:Number(input.value));input.title='Qty order: '+result.crt+' CRT / '+result.pcs+' PCS';}
 function renderRows(){
  document.querySelector('#monthly-lines').innerHTML=rows.length?'<label class="monthly-all"><input type="checkbox" id="monthly-select-all" onchange="PO.monthly.selectAll(this.checked)"> Pilih semua barang</label><div class="forecast-table-wrap"><table class="forecast-table excel-table"><colgroup>'+[5,12,22,12,12,9,14,14].map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr><th aria-label="Pilih"></th><th>Kode</th><th>Nama barang</th><th>Qty Forecast</th><th>Qty Order</th><th>Satuan</th><th>Forecast CRT</th><th>Forecast PCS</th></tr></thead><tbody>'+rows.map((r,i)=>{const p=S.data.products.find(p=>p.id===r.product_code&&p.supplier_id===supplierId),valid=p&&M.productPack(p).units.includes(r.unit),converted=conversions(r,Number(r.qty));return '<tr><td><input type="checkbox" aria-label="Pilih '+esc(r.product_code)+'" class="monthly-pick" data-index="'+i+'" '+(valid?'':'disabled')+' onchange="PO.monthly.selectionChanged()"></td><td>'+esc(r.product_code)+'</td><td>'+esc(r.name)+(valid?'':'<small>Satuan berubah, perbarui forecast</small>')+'</td><td class="forecast-reference numeric">'+esc(r.qty)+'</td><td><input aria-label="Qty '+esc(r.product_code)+'" class="monthly-qty" data-index="'+i+'" type="number" min="1" max="10000000" step="1" value="'+r.qty+'" '+(valid?'':'disabled')+' oninput="PO.monthly.updateQty('+i+')"></td><td>'+esc(r.unit)+'</td><td class="forecast-crt numeric">'+esc(converted.crt)+'</td><td class="forecast-pcs numeric">'+esc(converted.pcs)+'</td></tr>'}).join('')+'</tbody></table></div><p class="sub">Qty Forecast, Forecast CRT dan Forecast PCS tetap sebagai acuan. Isi Qty Order untuk pesanan; angka forecast tidak berubah. Tanda &mdash; berarti satuan belum terdaftar. CRT ditampilkan maksimal satu angka desimal.</p><div class="monthly-selection"><span id="monthly-selected-count">0 barang dipilih</span><button id="monthly-use" class="btn primary" disabled onclick="PO.monthly.useSelected()">Lanjut ke Draft PO</button></div>':'<p class="empty">Belum ada barang untuk periode dan supplier ini. Unggah forecast terlebih dahulu.</p>';
 }

 function selectionChanged(){if(!active())return;const all=[...document.querySelectorAll('.monthly-pick:not(:disabled)')],chosen=all.filter(n=>n.checked).length;document.querySelector('#monthly-selected-count').textContent=chosen+' barang dipilih';document.querySelector('#monthly-use').disabled=!chosen;const selectAll=document.querySelector('#monthly-select-all');selectAll.checked=!!all.length&&chosen===all.length;selectAll.indeterminate=chosen>0&&chosen<all.length}
 function selectAll(checked){document.querySelectorAll('.monthly-pick:not(:disabled)').forEach(n=>n.checked=checked);selectionChanged()}
 function useSelected(){if(!active())return;try{const selected=[...document.querySelectorAll('.monthly-pick:checked')].map(n=>{const i=Number(n.dataset.index),r=rows[i],input=document.querySelector('.monthly-qty[data-index="'+i+'"]');if(!input.reportValidity())throw Error('Periksa qty barang yang dipilih.');return {product_code:r.product_code,name:r.name,unit:r.unit,qty:Number(input.value)}});M.validateItems(selected);startDraft({supplier_id:supplierId,period,items:selected})}catch(e){toast(e.message)}}
 function preview(){document.querySelector('#monthly-review').innerHTML=review.length?'<div class="format">'+review.length+' barang / '+new Set(review.map(r=>r.supplier_id)).size+' supplier / '+new Set(review.map(r=>r.period)).size+' periode. Belum ada PO yang dibuat.</div><div class="table-wrap"><table class="excel-table"><thead><tr><th>Periode</th><th>Supplier</th><th>Kode / Barang</th><th>Satuan</th><th>Qty awal</th></tr></thead><tbody>'+review.slice(0,20).map(r=>'<tr><td>'+esc(r.period)+'</td><td>'+esc(r.supplier_id)+'</td><td>'+esc(r.product_code)+' / '+esc(r.name)+'</td><td>'+esc(r.unit)+'</td><td>'+r.qty+'</td></tr>').join('')+'</tbody></table></div><p class="sub">Pratinjau 20 baris pertama. Impor ini menyimpan master, bukan membuat PO.</p><button class="btn primary" onclick="PO.monthly.commit()">Simpan Forecast</button>':''}
 async function readFile(file){if(!file||!active())return;const run=++uploadEpoch,epoch=S.epoch;review=[];preview();try{if(!ready)throw Error('Tunggu master selesai dimuat.');if(file.size>5*1024*1024)throw Error('File maksimal 5 MB.');if(!window.XLSX)throw Error('Pembaca Excel belum tersedia. Periksa koneksi.');const bytes=await file.arrayBuffer();if(run!==uploadEpoch||epoch!==S.epoch||!active())return;const book=XLSX.read(bytes,{type:'array',raw:true});review=M.parseMonthlyImport(XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:'',raw:false}),S.data.suppliers,S.data.products);preview()}catch(e){if(run===uploadEpoch&&epoch===S.epoch&&active()){review=[];preview();showError(e)}}}
 async function commit(){if(S.busy||!active()||!ready||!review.length)return;const epoch=S.epoch;S.busy=true;document.body.classList.add('cloud-busy');try{const chosen=review[0];await rpc('po_monthly_import',{entries:review,versions:Object.fromEntries(headers.map(h=>[h.period,h.revision]))});if(epoch!==S.epoch||!active())return;review=[];preview();period=chosen.period;supplierId=chosen.supplier_id;await loadHeaders();toast('Forecast tersimpan. Pilih barang untuk membuat PO.')}catch(e){if(epoch===S.epoch)showError(e)}finally{S.busy=false;document.body.classList.remove('cloud-busy')}}
 function template(){const p=S.data.products.find(p=>S.data.suppliers.some(s=>s.id===p.supplier_id&&s.active)),quote=v=>'"'+String(v).replaceAll('"','""')+'"';const row=[period,p?.supplier_id||'SUP001',p?.id||'BRG001',p?.name||'Nama barang',M.productPack(p).units[0],10];download('template-master-po-bulanan.csv','\ufeff'+['periode,kode supplier,kode barang,nama barang,satuan,qty awal',row.map(quote).join(',')].join('\r\n'),'text/csv')}
 return {updateQty,page,readFile,commit,template,selectAll,selectionChanged,useSelected,choosePeriod:value=>{period=value;loadRows()},chooseSupplier:value=>{supplierId=value;loadRows()},reload:()=>{if(S.busy)return;review=[];uploadEpoch++;preview();ready=false;loadHeaders()}};
};
